package com.motionstudio.part2
import kotlin.math.*
data class ColorSettings(val exposure:Float=0f,val gamma:Float=1f,val brightness:Float=0f,val contrast:Float=1f,val saturation:Float=1f,val temperature:Float=0f,val tint:Float=0f,val lift:Rgba=Rgba(0f,0f,0f,0f),val gain:Rgba=Rgba(1f,1f,1f,1f),val shadows:Float=0f,val midtones:Float=0f,val highlights:Float=0f)
object ColorPipeline { fun process(src:FrameBuffer,s:ColorSettings):FrameBuffer{require(s.gamma>0);val o=FrameBuffer(src.width,src.height);for(y in 0 until src.height)for(x in 0 until src.width){val c=src.get(x,y);val l=.2126f*c.r+.7152f*c.g+.0722f*c.b;val sh=(1-l).coerceIn(0f,1f);val hi=l.coerceIn(0f,1f);val mid=1f-abs(l-.5f)*2f;var r=c.r*2f.pow(s.exposure)*s.gain.r+s.lift.r;var g=c.g*2f.pow(s.exposure)*s.gain.g+s.lift.g;var b=c.b*2f.pow(s.exposure)*s.gain.b+s.lift.b;r+=s.shadows*sh+s.midtones*mid+s.highlights*hi;g+=s.shadows*sh+s.midtones*mid+s.highlights*hi;b+=s.shadows*sh+s.midtones*mid+s.highlights*hi;r=((r-.5f)*s.contrast+.5f+s.brightness);g=((g-.5f)*s.contrast+.5f+s.brightness);b=((b-.5f)*s.contrast+.5f+s.brightness);r+=s.temperature*.1f;b-=s.temperature*.1f;g+=s.tint*.05f;val q=.2126f*r+.7152f*g+.0722f*b;r=q+(r-q)*s.saturation;g=q+(g-q)*s.saturation;b=q+(b-q)*s.saturation;val inv=1/s.gamma;o.set(x,y,Rgba(r.coerceIn(0f,1f).pow(inv),g.coerceIn(0f,1f).pow(inv),b.coerceIn(0f,1f).pow(inv),c.a))};return o}
 fun matrix(s:ColorSettings):FloatArray {val sat=s.saturation;return floatArrayOf(.2126f*(1-sat)+1,.7152f*(1-sat),.0722f*(1-sat),.2126f*(1-sat),.7152f*(1-sat)+1,.0722f*(1-sat),.2126f*(1-sat),.7152f*(1-sat),.0722f*(1-sat)+1)} }
